parameters.functionCode:
// Simulação de extração de leads (instaloader mock)
// Em produção, conectar com service de scraping real
const leads = [];
const count = Math.floor(Math.random() * 5) + 3; // 3-7 leads por simulação

for (let i = 0; i < count; i++) {
  leads.push({
    id: Math.random().toString(36).substr(2, 9),
    organizationId: $json.organizationId,
    source: 'instagram',
    contact: `55${Math.floor(Math.random() * 9000000000 + 1000000000)}`,
    metadata: {
      name: `Lead ${i + 1}`,
      targetProfile: $json.targetProfile || 'unknown',
      city: $json.city || 'unknown',
      gender: $json.gender || null,
      provider: $json.provider,
      extractedAt: $json.triggeredAt
    },
    status: 'pending',
    createdAt: $json.triggeredAt,
    updatedAt: $json.triggeredAt
  });
}

return {
  organizationId: $json.organizationId,
  triggerId: $json.triggerId,
  leadsExtracted: leads.length,
  leads: leads
};

